mapper.select:
SELECT f.id, f.listing_id, f.store_id, f.method, f.fixed_method, f.mape_ma, f.mape_wma, f.mape_holt, f.mape_seasonal, f.history_daily, f.forecast30, f.forecast60, f.forecast90, f.sigma, f.generated_time, s.name AS store_name, s.platform, l.seller_sku, l.title, m.code AS material_code, m.name AS material_name FROM ecom_forecast_sku f JOIN ecom_listing l ON l.id = f.listing_id JOIN ecom_store s ON s.id = f.store_id LEFT JOIN wms_material m ON m.id = l.material_id
f.store_id = #{storeId} AND f.method = #{method}
AND f.listing_id IN #{id}
AND (l.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR l.title LIKE CONCAT('%', #{keyword}, '%') OR m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY f.forecast30 DESC, f.listing_id
